contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We cannot access c.balances (it's not public), so observe only address(c).balance and whether the call reverts.
    // Ensure the test contract has no reliance on its own Ether balance for calling withdraw.
    function run(uint256 amount) public payable {
        // Read observable before the call
        uint256 beforeContractBalance = address(c).balance;

        // Attempt withdraw and catch whether it reverts
        bool withdrew;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        uint256 afterContractBalance = address(c).balance;

        // If withdraw reverted, contract balance must be unchanged. If it succeeded, contract balance must have decreased by exactly amount.
        assert((!withdrew && afterContractBalance == beforeContractBalance) || (withdrew && beforeContractBalance >= amount && afterContractBalance + amount == beforeContractBalance));
    }

    receive() external payable {}
}

