// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amount) internal {
        uint256 beforeContractBalance = address(c).balance;
        bool withdrew;
        try c.withdraw(amount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 afterContractBalance = address(c).balance;
        assertTrue((!withdrew && afterContractBalance == beforeContractBalance) || (withdrew && beforeContractBalance >= amount && afterContractBalance + amount == beforeContractBalance));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
